// =============================================================================
// CHROMADIARIES BRAND ASSETS & HIGH-RES PRINT ASSETS (BASE64 DATA URLs)
// Ensures 100% reliable image rendering in browser print popups, PDFs & offline
// =============================================================================

export const CHROMA_LOGO_BASE64 = 'data:image/png;base64,';
export const GM_SIGN_BASE64 = 'data:image/png;base64,';
export const WHITE_ICON_BASE64 = 'data:image/png;base64,';

export const CHROMA_LOGO_PATH = '/logo.png';
export const GM_SIGN_PATH = '/sign.png';
export const WHITE_ICON_PATH = '/white.png';

/**
 * Standard Print Header HTML
 */
export function getPrintHeaderHtml(title: string, subtitle: string, metaRight?: string): string {
  return `
    <div style="display: flex; justify-content: space-between; align-items: center; border-bottom: 2px solid #059669; padding-bottom: 12px; margin-bottom: 20px;">
      <div style="display: flex; align-items: center; gap: 14px;">
        <img src="${CHROMA_LOGO_BASE64}" alt="ChromaDiaries" style="height: 48px; max-width: 180px; object-fit: contain;" />
        <div>
          <div style="font-size: 18px; font-weight: 800; color: #059669; letter-spacing: -0.5px; line-height: 1.2;">${title}</div>
          <div style="font-size: 11px; color: #64748b; margin-top: 2px;">${subtitle}</div>
        </div>
      </div>
      <div style="text-align: right; font-size: 11px; color: #64748b;">
        ${metaRight || ''}
      </div>
    </div>
  `;
}

/**
 * Standard GM Signature Footer HTML
 */
export function getGmSignatureHtml(designation = 'General Manager (GM)', departmentText = 'ChromaDiaries Executive Oversight'): string {
  return `
    <div style="margin-top: 28px; padding-top: 14px; border-top: 1px solid #e2e8f0; display: flex; justify-content: space-between; align-items: flex-end; page-break-inside: avoid;">
      <div style="font-size: 10px; color: #94a3b8;">
        <div>Official Verified ChromaDiaries Workspace Record • www.chromadiaries.in</div>
        <div>Confidential & Authoritative Documentation</div>
      </div>
      <div style="text-align: center; min-width: 180px;">
        <img src="${GM_SIGN_BASE64}" alt="GM Signature" style="height: 52px; max-width: 160px; object-fit: contain; margin: 0 auto 4px auto; display: block;" />
        <div style="border-top: 1.5px solid #0f172a; padding-top: 4px; font-size: 11px; font-weight: 700; color: #0f172a;">
          ${designation}
        </div>
        <div style="font-size: 9px; color: #64748b; font-weight: 600;">
          ${departmentText}
        </div>
      </div>
    </div>
  `;
}